// OPTIONAL model classification via Responses API. No facts or answers generated by the LLM.
// Configured only when OPENAI_API_KEY and OPENAI_MODEL environment variables are present.
import {INTENTS} from './intents.js';
const modelOptions = [INTENTS.PROJECT, INTENTS.READING, INTENTS.JOB, INTENTS.UNCLEAR, INTENTS.OUT];
export async function modelIntent(question, fetcher = fetch) {
  if (!process.env.OPENAI_API_KEY || !process.env.OPENAI_MODEL) return null;
  const response = await fetcher('https://api.openai.com/v1/responses', {
    method: 'POST', signal: AbortSignal.timeout(8000),
    headers: {'Content-Type':'application/json','Authorization':`Bearer ${process.env.OPENAI_API_KEY}`},
    body: JSON.stringify({ model:process.env.OPENAI_MODEL, store:false,
      instructions:'You are an intent classifier for a personal portfolio page. Allowed capabilities (enforced by server): answer_from_record, answer_from_external_api, ask_clarifying_question, refuse_unpublished_fact, report_out_of_scope. You may never send emails, book meetings, speak for Sharif, reveal unpublished facts, or invent biography. Choose only one permitted intent from the provided JSON schema. Do not produce answers or facts.',
      input: question,
      text:{format:{type:'json_schema',name:'portfolio_intent',strict:true,
        schema:{type:'object',properties:{intent:{type:'string',enum:modelOptions}},required:['intent'],additionalProperties:false}}}
    })
  });
  if (!response.ok) return null;
  const data = await response.json();
  const raw = (data.output || []).flatMap(x=>x.content || []).find(c=>c.type==='output_text')?.text;
  if (!raw) return null;
  try { const obj=JSON.parse(raw); return modelOptions.includes(obj.intent) ? obj.intent : null; }
  catch { return null; }
}
